ALTER SESSION SET CONTAINER = XEPDB1;


-- Create tablespaces (adjusted paths for Linux inside container)
CREATE TABLESPACE dados_acad
  LOGGING
  DATAFILE '/opt/oracle/oradata/XE/dados_acad.dbf'
  SIZE 500M
  AUTOEXTEND ON NEXT 100M MAXSIZE 3072M
  EXTENT MANAGEMENT LOCAL;

CREATE TABLESPACE indices_acad
  LOGGING
  DATAFILE '/opt/oracle/oradata/XE/indices_acad.dbf'
  SIZE 200M
  AUTOEXTEND ON NEXT 10M MAXSIZE 1024M
  EXTENT MANAGEMENT LOCAL;

CREATE TEMPORARY TABLESPACE temp_acad
  TEMPFILE '/opt/oracle/oradata/XE/temp_acad.dbf'
  SIZE 50M
  AUTOEXTEND ON NEXT 10M MAXSIZE 200M
  EXTENT MANAGEMENT LOCAL;

-- Create user
CREATE USER academico
  IDENTIFIED BY academico
  DEFAULT TABLESPACE dados_acad
  TEMPORARY TABLESPACE temp_acad
  PROFILE DEFAULT
  QUOTA UNLIMITED ON dados_acad
  QUOTA UNLIMITED ON indices_acad;

-- Grant privileges
GRANT CONNECT, RESOURCE, CREATE VIEW TO academico;

-- Grant unlimited tablespace usage
GRANT UNLIMITED TABLESPACE TO academico;


alter session set current_schema = ACADEMICO
/

CREATE TABLE ALUNOS 
    ( 
     MAT_ALU NUMBER (10)  NOT NULL , 
     NOM_ALU VARCHAR2 (50)  NOT NULL , 
     TOT_CRED NUMBER (3)  NOT NULL , 
     DAT_NASC DATE  NOT NULL , 
     MGP NUMBER (4,2)  NOT NULL , 
     COD_CURSO NUMBER (3)  NOT NULL 
    ) TABLESPACE DADOS_ACAD
;



ALTER TABLE ALUNOS 
    ADD CONSTRAINT ALU_MAT_ALU_CK 
    CHECK (MAT_ALU > 0)
        INITIALLY IMMEDIATE 
        ENABLE 
        VALIDATE 
;


ALTER TABLE ALUNOS 
    ADD CONSTRAINT ALU_TOT_CRED_CK 
    CHECK (TOT_CRED >= 0)
        INITIALLY IMMEDIATE 
        ENABLE 
        VALIDATE 
;


ALTER TABLE ALUNOS 
    ADD CONSTRAINT ALU_MGP_CK 
    CHECK (MGP BETWEEN 0 and 10)
        INITIALLY IMMEDIATE 
        ENABLE 
        VALIDATE 
;


ALTER TABLE ALUNOS 
    ADD CONSTRAINT ALU_COD_CURSO_CK 
    CHECK (COD_CURSO > 0)
        INITIALLY IMMEDIATE 
        ENABLE 
        VALIDATE 
;

CREATE UNIQUE INDEX ALU_PKX ON ALUNOS 
    ( 
     MAT_ALU ASC 
    ) TABLESPACE INDICES_ACAD
;

CREATE INDEX ALU_CUR_FKX ON ALUNOS 
    ( 
     COD_CURSO ASC 
    ) TABLESPACE INDICES_ACAD 
;

ALTER TABLE ALUNOS 
    ADD CONSTRAINT ALU_PK PRIMARY KEY ( MAT_ALU );


